class Solution:
    def checktree(self, preorder, inorder, postorder, N):
        # function to build postorder from preorder and inorder
        def build(pre, ino):
            if not pre:
                return []
            root = pre[0]
            idx = ino.index(root)
            left = build(pre[1:idx+1], ino[:idx])
            right = build(pre[idx+1:], ino[idx+1:])
            return left + right + [root]

        # generate postorder
        generated_post = build(preorder, inorder)

        # compare
        if generated_post == postorder:
            return True
        else:
            return False
